    sqlx::query_as(
        "SELECT status, retry_count, retry_after IS NULL, lease_token IS NOT NULL, \
                lease_until IS NOT NULL, published_at IS NULL, dlx_at IS NULL, abandoned_at IS NULL \
         FROM outbox WHERE event_id = $1",
    )
    .bind(event_id)
