            store
                .run_global_transaction::<_, _, sqlx::Error>(|cap| {
                    Box::pin(async move {
                        let _outcome = append_outbox(cap, &entry, &env)
                            .await
                            .map_err(test_append_error)?;
                        Ok(())
                    }) as BoxFuture<'_, Result<(), sqlx::Error>>
                })
