// ── F8：真实 DB liveness 采样集成验证 ─────────────────────────────────────────

/// t50：真实 DB 连接下 `probe_db_liveness` 返回 Ready。
///
/// 验证：`SELECT 1` 成功 → `PoolReadiness::Ready`（端到端 DB 可达性真实探针）。
#[tokio::test(flavor = "multi_thread")]
async fn probe_db_liveness_returns_ready_with_live_db() -> TestResult {
    use crate::pool::PoolReadiness;

    let (_pg, store) = connect_pg().await?;
    store.run_migrations().await?;

    let result = store.probe_db_liveness().await;
    assert_eq!(
        result,
        PoolReadiness::Ready,
        "t50: 真实 DB 连接下 probe_db_liveness 应返回 Ready"
    );

    store.shutdown().await?;
    Ok(())
}

/// A reader whose only established connection is in use is capacity pressure, not evidence that
/// PostgreSQL is down. Readiness must stay HTTP-servable through the Saturated state.
#[tokio::test(flavor = "multi_thread")]
async fn probe_db_liveness_marks_full_reader_saturated() -> TestResult {
    use std::time::Duration;

    use crate::pool::{PgTenantReadConfig, PoolReadiness};

    let (pg, owner) = connect_pg().await?;
    owner.run_migrations().await?;
    let base_config = rss_app_read_config(&pg, &owner).await?;
    let constrained_config = PgTenantReadConfig::new(
        base_config
            .as_pg_config()
            .clone()
            .with_max_connections(1)
            .with_acquire_timeout(Duration::from_secs(30)),
    );
    let reader = PgStore::connect_verified_read(&constrained_config)
        .await?
        .store_arc();

    let only_connection = reader.pool.acquire().await?;

    assert_eq!(
        reader.probe_db_liveness().await,
        PoolReadiness::Saturated,
        "a fully occupied reader pool must remain degraded-but-ready"
    );

    drop(only_connection);
    reader.shutdown().await?;
    owner.shutdown().await?;
    Ok(())
}

/// Once the probe owns an idle connection, a backend/query hang is liveness failure rather than
/// capacity pressure. The production path uses `SELECT 1`; this test-only query exercises the same
/// acquired-connection deadline against a real PostgreSQL backend.
#[tokio::test(flavor = "multi_thread")]
async fn probe_db_liveness_marks_hung_idle_backend_down() -> TestResult {
    use std::time::Duration;

    use crate::pool::{PgTenantReadConfig, PoolReadiness};

    let (pg, owner) = connect_pg().await?;
    owner.run_migrations().await?;
    let base_config = rss_app_read_config(&pg, &owner).await?;
    let constrained_config = PgTenantReadConfig::new(
        base_config
            .as_pg_config()
            .clone()
            .with_max_connections(1)
            .with_acquire_timeout(Duration::from_secs(30)),
    );
    let reader = PgStore::connect_verified_read(&constrained_config)
        .await?
        .store_arc();
    for _ in 0..20 {
        if reader.pool.num_idle() > 0 {
            break;
        }
        tokio::time::sleep(Duration::from_millis(25)).await;
    }
    assert_eq!(
        reader.pool.num_idle(),
        1,
        "test precondition: the probe must begin with one idle backend"
    );

    assert_eq!(
        reader
            .probe_db_liveness_query_for_test("SELECT pg_sleep(4)")
            .await,
        PoolReadiness::Down,
        "a query hang after acquiring an idle backend must fail closed"
    );

    reader.shutdown().await?;
    owner.shutdown().await?;
    Ok(())
}

/// t51：起 sampling loop 推进一 tick → health 反映 Ready。
///
/// 验证：`pg_readiness_sampling_loop` 在真实 DB 下一轮 tick 后
/// `PgDbReadiness::snapshot()` 返回 `PoolReadiness::Ready`。
#[tokio::test(flavor = "multi_thread")]
async fn sampling_loop_marks_ready_with_live_db() -> TestResult {
    use std::sync::Arc;
    use std::time::Duration;

    use tokio_util::sync::CancellationToken;

    use crate::pool::PoolReadiness;
    use crate::readiness::{PgDbReadiness, pg_readiness_sampling_loop};

    let (_pg, store) = connect_pg().await?;
    store.run_migrations().await?;

    let store = Arc::new(store);
    let health = Arc::new(PgDbReadiness::new());
    let token = CancellationToken::new();

    // 短 period 确保首 tick 快速到来（集成测试真实时间，不 pause）。
    let handle = tokio::spawn(pg_readiness_sampling_loop(
        Arc::clone(&store),
        Arc::clone(&store),
        Duration::from_millis(50),
        token.clone(),
        Arc::clone(&health),
    ));

    // 等待至少一轮 tick 完成（period=50ms，sleep 300ms 留足余量）。
    tokio::time::sleep(Duration::from_millis(300)).await;

    assert_eq!(
        health.snapshot(),
        PoolReadiness::Ready,
        "t51: 真实 DB 一 tick 后 health 应为 Ready"
    );

    token.cancel();
    assert!(handle.await.is_ok(), "sampling loop 应正常退出");

    // reason: Arc<PgStore> 在此作用域末尾 drop；pool 关闭由 Arc drop 时触发，
    // 集成测试无需显式 shutdown Arc<PgStore>（与 Arc 所有权语义一致）。
    Ok(())
}

/// A failed dedicated reader must degrade aggregate PostgreSQL readiness even while the writer
/// remains reachable.
#[tokio::test(flavor = "multi_thread")]
async fn sampling_loop_marks_down_when_reader_pool_is_closed() -> TestResult {
    use std::sync::Arc;
    use std::time::Duration;

    use tokio_util::sync::CancellationToken;

    use crate::pool::PoolReadiness;
    use crate::readiness::{PgDbReadiness, pg_readiness_sampling_loop};

    let (pg, writer) = connect_pg().await?;
    writer.run_migrations().await?;
    let reader_config = rss_app_read_config(&pg, &writer).await?;
    let reader = PgStore::connect_verified_read(&reader_config)
        .await?
        .store_arc();
    reader.shutdown().await?;

    let writer = Arc::new(writer);
    let health = Arc::new(PgDbReadiness::new());
    let token = CancellationToken::new();
    let handle = tokio::spawn(pg_readiness_sampling_loop(
        Arc::clone(&writer),
        reader,
        Duration::from_millis(50),
        token.clone(),
        Arc::clone(&health),
    ));

    tokio::time::sleep(Duration::from_millis(300)).await;
    assert_eq!(
        health.snapshot(),
        PoolReadiness::Down,
        "closed reader must dominate a healthy writer"
    );

    token.cancel();
    assert!(handle.await.is_ok(), "sampling loop should stop cleanly");
    writer.shutdown().await?;
    Ok(())
}

// ───────────────────────────────────────────────────────────────────────────
// PgCredentialRepo（identity 凭据仓储）集成测试（#1316）：find/save/upsert · authenticate 三态（含成功清锁）·
// 折叠锁定态原子 RMW（累计→锁→lazy-unlock 持久化）· password-change CAS · 跨租 fail-closed · F2 未知主体不建行 ·
// information_schema 明文列断言（DoD）。
//
// 构造 `Credential` 经 `Credential::hydrate`（pub funnel + secure typed test seam）；`LoginIdentifier` 经
// `identity::test_support::login_identifier`（`pub(crate)` funnel 经 test-support feature 暴露，同
// `test_support::session` 范式）。锁定策略阈值（5 次 / 15min 窗口 / 15min TTL）域 `AccountLockout` 单源，
// adapter 仅 I/O；`now` 由测试直传（确定性，无需 Clock）。known/wrong/correct/lazy-unlock 行为镜像 in-mem
// `InMemCredentialRepo` 单测（crates/identity/src/internal/mem.rs），此处证 postgres provider 行为等价 + durable。
// ───────────────────────────────────────────────────────────────────────────

use identity::ports::{
    AuthOutcome, Credential, CredentialRepo, LoginIdentifier, PasswordChangeMutation,
};

use crate::PgCredentialRepo;
use crate::credential_repo::CredentialMutationFault;

const CRED_TENANT_A: &str = "a1a2a3a4-b1b2-4c3c-8d4d-e1e2e3e4e5e6";
const CRED_TENANT_B: &str = "b9b8b7b6-c5c4-4a3a-8f2f-d1d2d3d4d5d6";
const CRED_USER_ALICE: &str = "11111111-2222-4333-8444-555555555555";
const CRED_USER_BOB: &str = "22222222-3333-4444-8555-666666666666";
const CRED_USER_RETRY: &str = "33333333-4444-4555-8666-777777777777";
// 锁定 TTL（域 AccountLockout 单源镜像；仅供测试时间步进推算，非生产复刻）。
const LOCK_TTL_SECS: u64 = 15 * 60;
// 测试基准时刻（well-after-epoch，避开 unix_secs 的 epoch 前钳零边界）。
const CRED_BASE_SECS: u64 = 1_700_000_000;

type CredHelperResult<T> = Result<T, Box<dyn std::error::Error + Send + Sync>>;

fn cred_tenant(raw: &str) -> CredHelperResult<TenantId> {
    Ok(TenantId::parse(raw)?)
}

fn cred_uid(raw: &str) -> CredHelperResult<ids::UserId> {
    Ok(ids::UserId::parse(raw)?)
}

// 登录查找键（经 test-support funnel；known 主体亦可 `cred.login().clone()`，未知主体仅经此入口）。
fn login_id(raw: &str) -> LoginIdentifier {
    identity::test_support::login_identifier(raw)
}

fn raw_password(raw: &str) -> secure::RawPassword {
    secure::RawPassword::new(raw.to_owned())
}

fn test_password_hash(password: &str) -> CredHelperResult<secure::PasswordHash> {
    Ok(secure::PasswordHash::for_test(raw_password(password))?)
}

fn password_matches(password: &str, hash: &secure::PasswordHash) -> CredHelperResult<bool> {
    Ok(matches!(
        secure::verify_password(raw_password(password), Some(hash))?,
        secure::PasswordVerification::Verified(_)
    ))
}

fn make_cred_with_hash(
    login: &str,
    user: &str,
    hash: secure::PasswordHash,
    version: u32,
    tenant: TenantId,
) -> CredHelperResult<Credential> {
    Ok(Credential::hydrate(
        login,
        cred_uid(user)?,
        tenant,
        hash,
        version,
    ))
}

fn make_cred(
    login: &str,
    user: &str,
    password: &str,
    version: u32,
    tenant: TenantId,
) -> CredHelperResult<Credential> {
    make_cred_with_hash(login, user, test_password_hash(password)?, version, tenant)
}

fn password_change(expected: u32, next: Credential) -> PasswordChangeMutation {
    PasswordChangeMutation::for_test(expected, next)
}

fn cred_epoch(secs: u64) -> std::time::SystemTime {
    std::time::SystemTime::UNIX_EPOCH + std::time::Duration::from_secs(secs)
}

// 直查持久化 failure_count（断言锁定态原子推进 / 清零）。
async fn db_failure_count(store: &PgStore, tenant: &str, login: &str) -> CredHelperResult<i64> {
    let row: (i64,) = sqlx::query_as(
        "SELECT failure_count FROM credentials WHERE tenant_id = $1::uuid AND login = $2",
    )
    .bind(tenant)
    .bind(login)
    .fetch_one(&store.pool)
    .await?;
    Ok(row.0)
}

async fn owner_credential_snapshot(
    owner: &PgStore,
    tenant: TenantId,
    login: &str,
) -> Result<Option<(i64, String)>, sqlx::Error> {
    sqlx::query_as(
        "SELECT version, password_hash FROM credentials \
         WHERE tenant_id = $1::uuid AND login = $2",
    )
    .bind(tenant.as_uuid().to_string())
    .bind(login)
    .fetch_optional(&owner.pool)
    .await
}

type CredentialAuthState = (i64, String, i64, Option<i64>, Option<i64>);

async fn owner_credential_auth_state(
    owner: &PgStore,
    tenant: TenantId,
    login: &str,
) -> Result<Option<CredentialAuthState>, sqlx::Error> {
    sqlx::query_as(
        "SELECT version, password_hash, failure_count, \
         extract(epoch from lockout_window_start)::bigint, \
         extract(epoch from locked_until)::bigint \
         FROM credentials WHERE tenant_id = $1::uuid AND login = $2",
    )
    .bind(tenant.as_uuid().to_string())
    .bind(login)
    .fetch_optional(&owner.pool)
    .await
}

// 直查持久化 locked_until epoch（NULL → None；断言 lazy-unlock 持久化解锁）。
async fn db_locked_until(
    store: &PgStore,
    tenant: &str,
    login: &str,
) -> CredHelperResult<Option<i64>> {
    let row: (Option<i64>,) = sqlx::query_as(
        "SELECT extract(epoch from locked_until)::bigint \
         FROM credentials WHERE tenant_id = $1::uuid AND login = $2",
    )
    .bind(tenant)
    .bind(login)
    .fetch_one(&store.pool)
    .await?;
    Ok(row.0)
}

// CRUD：未存 → None；save → find_by_user_id 往返一致（user_id/login/version + PHC 列形态）；同 login 二次 save
// → upsert 覆盖 version（非新增行）。
#[tokio::test(flavor = "multi_thread")]
async fn credential_repo_save_find_roundtrip_and_upsert() -> TestResult {
    let (_pg, store) = connect_pg().await?;
    store.run_migrations().await?;
    let repo = PgCredentialRepo::from_unverified_for_test(&store);
    let tenant = cred_tenant(CRED_TENANT_A)?;

    // 未保存 → None（fail-closed 基线，anti-vacuity 负例）。
    assert!(
        repo.find_by_user_id(identity_scope(tenant), cred_uid(CRED_USER_ALICE)?)
            .await?
            .is_none(),
        "未保存 → None"
    );

    // save → find_by_user_id 往返一致。
    repo.save(
        identity_scope(tenant),
        make_cred("alice", CRED_USER_ALICE, "pw1", 1, tenant)?,
    )
    .await?;
    let Some(got) = repo
        .find_by_user_id(identity_scope(tenant), cred_uid(CRED_USER_ALICE)?)
        .await?
    else {
        return Err("saved credential visible".into());
    };
    assert_eq!(
        got.user_id(),
        cred_uid(CRED_USER_ALICE)?,
        "canonical subject 保真"
    );
    assert_eq!(got.login().as_str(), "alice", "login 查找键保真");
    assert_eq!(got.version(), 1, "version 保真");
    assert!(
        got.password_hash().as_str().starts_with("$argon2"),
        "回读 PHC 为 argon2 格式（明文永不落库）"
    );

    // 同 login 二次 save → upsert 覆盖 version（DO UPDATE，非新增行）。
    repo.save(
        identity_scope(tenant),
        make_cred("alice", CRED_USER_ALICE, "pw2", 2, tenant)?,
    )
    .await?;
    let Some(got2) = repo
        .find_by_user_id(identity_scope(tenant), cred_uid(CRED_USER_ALICE)?)
        .await?
    else {
        return Err("upserted credential visible".into());
    };
    assert_eq!(got2.version(), 2, "upsert 覆盖 version");
    let n: (i64,) = sqlx::query_as(
        "SELECT count(*) FROM credentials WHERE tenant_id = $1::uuid AND login = $2",
    )
    .bind(CRED_TENANT_A)
    .bind("alice")
    .fetch_one(&store.pool)
    .await?;
    assert_eq!(n.0, 1, "upsert 不新增行");

    store.shutdown().await?;
    Ok(())
}

// authenticate 三态：已知+正确 → Authenticated(canonical user_id)；已知+错 → InvalidKnownUser；
// 查无凭据 → InvalidUnknown（当前档 KDF 仍跑，不 panic）。
#[tokio::test(flavor = "multi_thread")]
async fn credential_repo_authenticate_known_wrong_and_unknown() -> TestResult {
    let (_pg, store) = connect_pg().await?;
    store.run_migrations().await?;
    let repo = PgCredentialRepo::from_unverified_for_test(&store);
    let tenant = cred_tenant(CRED_TENANT_A)?;
    repo.save(
        identity_scope(tenant),
        make_cred("alice", CRED_USER_ALICE, "correct", 1, tenant)?,
    )
    .await?;
    let now = cred_epoch(CRED_BASE_SECS);

    assert_eq!(
        repo.authenticate(
            identity_scope(tenant),
            login_id("alice"),
            raw_password("correct"),
            now
        )
        .await?,
        AuthOutcome::Authenticated(cred_uid(CRED_USER_ALICE)?),
        "已知+正确 → Authenticated(canonical user_id)"
    );
    assert_eq!(
        repo.authenticate(
            identity_scope(tenant),
            login_id("alice"),
            raw_password("wrong"),
            now
        )
        .await?,
        AuthOutcome::InvalidKnownUser,
        "已知+错 → InvalidKnownUser"
    );
    assert_eq!(
        repo.authenticate(
            identity_scope(tenant),
            login_id("ghost"),
            raw_password("correct"),
            now
        )
        .await?,
        AuthOutcome::InvalidUnknown,
        "查无凭据 → InvalidUnknown"
    );

    store.shutdown().await?;
    Ok(())
}

#[tokio::test(flavor = "multi_thread")]
async fn credential_repo_rehash_upgrades_weak_phc_without_bumping_version() -> TestResult {
    let (_pg, store) = connect_pg().await?;
    store.run_migrations().await?;
    let repo = PgCredentialRepo::from_unverified_for_test(&store);
    let tenant = cred_tenant(CRED_TENANT_A)?;
    let weak =
        secure::PasswordHash::for_test_with_params(raw_password("legacy-short"), 8 * 1024, 1, 1)?;
    let weak_phc = weak.as_str().to_owned();
    repo.save(
        identity_scope(tenant),
        make_cred_with_hash("alice", CRED_USER_ALICE, weak, 7, tenant)?,
    )
    .await?;

    assert_eq!(
        repo.authenticate(
            identity_scope(tenant),
            login_id("alice"),
            raw_password("wrong"),
            cred_epoch(CRED_BASE_SECS),
        )
        .await?,
        AuthOutcome::InvalidKnownUser
    );
    assert_eq!(
        owner_credential_snapshot(&store, tenant, "alice")
            .await?
            .ok_or("credential snapshot missing")?,
        (7, weak_phc.clone()),
        "failed verification must not replace PHC"
    );
    assert_eq!(
        repo.authenticate(
            identity_scope(tenant),
            login_id("alice"),
            raw_password("legacy-short"),
            cred_epoch(CRED_BASE_SECS),
        )
        .await?,
        AuthOutcome::Authenticated(cred_uid(CRED_USER_ALICE)?)
    );

    let (version, upgraded_phc) = owner_credential_snapshot(&store, tenant, "alice")
        .await?
        .ok_or("upgraded credential snapshot missing")?;
    let upgraded = secure::PasswordHash::parse(&upgraded_phc)?;
    assert_eq!(
        version, 7,
        "transparent rehash must preserve business version"
    );
    assert_ne!(upgraded_phc, weak_phc, "weak PHC must be replaced");
    assert!(
        !upgraded.needs_rehash()?,
        "replacement must use current profile"
    );
    assert!(password_matches("legacy-short", &upgraded)?);

    store.shutdown().await?;
    Ok(())
}

#[tokio::test(flavor = "multi_thread")]
async fn credential_repo_rehash_preserves_current_and_stronger_phc() -> TestResult {
    let (_pg, store) = connect_pg().await?;
    store.run_migrations().await?;
    let repo = PgCredentialRepo::from_unverified_for_test(&store);
    let tenant = cred_tenant(CRED_TENANT_A)?;
    let current = test_password_hash("current-password")?;
    let stronger = secure::PasswordHash::for_test_with_params(
        raw_password("stronger-password"),
        20 * 1024,
        3,
        2,
    )?;

    for (login, user, password, hash) in [
        ("current", CRED_USER_ALICE, "current-password", current),
        ("stronger", CRED_USER_BOB, "stronger-password", stronger),
    ] {
        let original_phc = hash.as_str().to_owned();
        repo.save(
            identity_scope(tenant),
            make_cred_with_hash(login, user, hash, 11, tenant)?,
        )
        .await?;
        assert_eq!(
            repo.authenticate(
                identity_scope(tenant),
                login_id(login),
                raw_password(password),
                cred_epoch(CRED_BASE_SECS),
            )
            .await?,
            AuthOutcome::Authenticated(cred_uid(user)?)
        );
        let (version, stored_phc) = owner_credential_snapshot(&store, tenant, login)
            .await?
            .ok_or("credential snapshot missing")?;
        assert_eq!(version, 11, "login must preserve business version");
        assert_eq!(
            stored_phc, original_phc,
            "current/stronger PHC must not be replaced"
        );
    }

    store.shutdown().await?;
    Ok(())
}

#[tokio::test(flavor = "multi_thread")]
async fn credential_repo_rehash_update_failure_rolls_back() -> TestResult {
    let (_pg, store) = connect_pg().await?;
    store.run_migrations().await?;
    let repo = PgCredentialRepo::from_unverified_for_test(&store);
    let tenant = cred_tenant(CRED_TENANT_A)?;
    let weak =
        secure::PasswordHash::for_test_with_params(raw_password("legacy-short"), 8 * 1024, 1, 1)?;
    let weak_phc = weak.as_str().to_owned();
    repo.save(
        identity_scope(tenant),
        make_cred_with_hash("alice", CRED_USER_ALICE, weak, 19, tenant)?,
    )
    .await?;
    sqlx::raw_sql(
        "CREATE FUNCTION reject_credential_rehash() RETURNS trigger LANGUAGE plpgsql AS $$ \
         BEGIN RAISE EXCEPTION 'injected rehash update failure'; END $$; \
         CREATE TRIGGER reject_credential_rehash BEFORE UPDATE OF password_hash ON credentials \
         FOR EACH ROW EXECUTE FUNCTION reject_credential_rehash();",
    )
    .execute(&store.pool)
    .await?;

    assert!(
        repo.authenticate(
            identity_scope(tenant),
            login_id("alice"),
            raw_password("legacy-short"),
            cred_epoch(CRED_BASE_SECS),
        )
        .await
        .is_err(),
        "rehash UPDATE failure must fail authentication closed"
    );
    let (version, stored_phc) = owner_credential_snapshot(&store, tenant, "alice")
        .await?
        .ok_or("credential snapshot missing")?;
    assert_eq!(version, 19);
    assert_eq!(
        stored_phc, weak_phc,
        "failed transaction must roll back PHC"
    );

    store.shutdown().await?;
    Ok(())
}

#[tokio::test(flavor = "multi_thread")]
async fn credential_repo_rehash_commit_failure_rolls_back_hash_and_lockout_clear() -> TestResult {
    let (_pg, store) = connect_pg().await?;
    store.run_migrations().await?;
    let repo = PgCredentialRepo::from_unverified_for_test(&store);
    let tenant = cred_tenant(CRED_TENANT_A)?;
    let weak =
        secure::PasswordHash::for_test_with_params(raw_password("legacy-short"), 8 * 1024, 1, 1)?;
    repo.save(
        identity_scope(tenant),
        make_cred_with_hash("alice", CRED_USER_ALICE, weak, 23, tenant)?,
    )
    .await?;
    sqlx::query(
        "UPDATE credentials SET failure_count = 4, \
         lockout_window_start = to_timestamp($3), locked_until = to_timestamp($4) \
         WHERE tenant_id = $1::uuid AND login = $2",
    )
    .bind(tenant.as_uuid().to_string())
    .bind("alice")
    .bind(i64::try_from(CRED_BASE_SECS - 60)?)
    .bind(i64::try_from(CRED_BASE_SECS + 900)?)
    .execute(&store.pool)
    .await?;
    let before = owner_credential_auth_state(&store, tenant, "alice")
        .await?
        .ok_or("credential state missing")?;
    sqlx::raw_sql(
        "CREATE SEQUENCE credential_rehash_commit_probe; \
         CREATE FUNCTION reject_credential_rehash_on_commit() RETURNS trigger LANGUAGE plpgsql AS $$ \
         BEGIN \
           IF OLD.password_hash IS DISTINCT FROM NEW.password_hash THEN \
             IF NOT EXISTS (SELECT 1 FROM credentials WHERE tenant_id = NEW.tenant_id \
             AND login = NEW.login AND failure_count = 0 \
               AND lockout_window_start IS NULL AND locked_until IS NULL) THEN \
               RAISE EXCEPTION 'rehash lockout clear missing'; \
             END IF; \
             PERFORM nextval('credential_rehash_commit_probe'); \
             RAISE EXCEPTION 'injected rehash commit failure'; \
           END IF; \
           RETURN NEW; \
         END $$; \
         CREATE CONSTRAINT TRIGGER reject_credential_rehash_on_commit AFTER UPDATE ON credentials \
         DEFERRABLE INITIALLY DEFERRED FOR EACH ROW \
         EXECUTE FUNCTION reject_credential_rehash_on_commit();",
    )
    .execute(&store.pool)
    .await?;

    let error = match repo
        .authenticate(
            identity_scope(tenant),
            login_id("alice"),
            raw_password("legacy-short"),
            cred_epoch(CRED_BASE_SECS),
        )
        .await
    {
        Err(error) => error,
        Ok(outcome) => return Err(format!("deferred trigger allowed commit: {outcome:?}").into()),
    };
    assert!(matches!(error, IdentityError::Storage(_)));
    let probe: (i64, bool) =
        sqlx::query_as("SELECT last_value, is_called FROM credential_rehash_commit_probe")
            .fetch_one(&store.pool)
            .await?;
    assert_eq!(
        probe,
        (1, true),
        "deferred trigger must observe the lockout clear before rejecting commit"
    );
    assert_eq!(
        owner_credential_auth_state(&store, tenant, "alice")
            .await?
            .ok_or("credential state missing after rollback")?,
        before,
        "commit failure must roll back PHC, version, and pre-existing lockout"
    );

    store.shutdown().await?;
    Ok(())
}

#[tokio::test(flavor = "multi_thread")]
async fn credential_repo_rehash_concurrent_logins_upgrade_weak_phc_once() -> TestResult {
    use std::sync::Arc;

    let (_pg, store) = connect_pg().await?;
    store.run_migrations().await?;
    let repo = Arc::new(PgCredentialRepo::from_unverified_for_test(&store));
    let tenant = cred_tenant(CRED_TENANT_A)?;
    let weak =
        secure::PasswordHash::for_test_with_params(raw_password("legacy-short"), 8 * 1024, 1, 1)?;
    repo.save(
        identity_scope(tenant),
        make_cred_with_hash("alice", CRED_USER_ALICE, weak, 17, tenant)?,
    )
    .await?;

    sqlx::query(
        "CREATE TABLE credential_rehash_updates (login text PRIMARY KEY, updates integer NOT NULL DEFAULT 0)",
    )
    .execute(&store.pool)
    .await?;
    sqlx::query("INSERT INTO credential_rehash_updates (login) VALUES ('alice')")
        .execute(&store.pool)
        .await?;
    sqlx::query(
        "CREATE FUNCTION count_credential_rehash_update() RETURNS trigger LANGUAGE plpgsql AS $$ \
         BEGIN IF OLD.password_hash IS DISTINCT FROM NEW.password_hash THEN \
         UPDATE credential_rehash_updates SET updates = updates + 1 WHERE login = NEW.login; \
         END IF; RETURN NEW; END $$",
    )
    .execute(&store.pool)
    .await?;
    sqlx::query(
        "CREATE TRIGGER count_credential_rehash_update AFTER UPDATE OF password_hash ON credentials \
         FOR EACH ROW EXECUTE FUNCTION count_credential_rehash_update()",
    )
    .execute(&store.pool)
    .await?;

    let mut handles = Vec::new();
    for _ in 0..2 {
        let repo = Arc::clone(&repo);
        handles.push(tokio::spawn(async move {
            repo.authenticate(
                identity_scope(tenant),
                login_id("alice"),
                raw_password("legacy-short"),
                cred_epoch(CRED_BASE_SECS),
            )
            .await
        }));
    }
    for handle in handles {
        assert_eq!(
            handle
                .await
                .map_err(|error| format!("join failed: {error}"))??,
            AuthOutcome::Authenticated(cred_uid(CRED_USER_ALICE)?)
        );
    }

    let (rehash_updates,): (i32,) =
        sqlx::query_as("SELECT updates FROM credential_rehash_updates WHERE login = 'alice'")
            .fetch_one(&store.pool)
            .await?;
    assert_eq!(
        rehash_updates, 1,
        "row lock must serialize rehash to one PHC replacement"
    );
    let (version, upgraded_phc) = owner_credential_snapshot(&store, tenant, "alice")
        .await?
        .ok_or("credential snapshot missing")?;
    assert_eq!(
        version, 17,
        "transparent rehash must preserve business version"
    );
    assert!(!secure::PasswordHash::parse(&upgraded_phc)?.needs_rehash()?);

    store.shutdown().await?;
    Ok(())
}

// F2：未知主体登录失败**不建行 / 不建锁**——不可经枚举撑大 credentials 表（折叠列 ⇒ 无行即无锁，结构层成立）。
#[tokio::test(flavor = "multi_thread")]
async fn credential_repo_unknown_subject_creates_no_row() -> TestResult {
    let (_pg, store) = connect_pg().await?;
    store.run_migrations().await?;
    let repo = PgCredentialRepo::from_unverified_for_test(&store);
    let tenant = cred_tenant(CRED_TENANT_A)?;
    repo.save(
        identity_scope(tenant),
        make_cred("alice", CRED_USER_ALICE, "correct", 1, tenant)?,
    )
    .await?;
    let now = cred_epoch(CRED_BASE_SECS);

    for i in 0..20 {
        assert_eq!(
            repo.authenticate(
                identity_scope(tenant),
                login_id(&format!("ghost-{i}")),
                raw_password("x"),
                now
            )
            .await?,
            AuthOutcome::InvalidUnknown
        );
    }
    // 仅 alice 一行（未知主体未建任何行 ⇒ lockout 表不随枚举增长，F2）。
    let n: (i64,) = sqlx::query_as("SELECT count(*) FROM credentials WHERE tenant_id = $1::uuid")
        .bind(CRED_TENANT_A)
        .fetch_one(&store.pool)
        .await?;
    assert_eq!(n.0, 1, "未知主体不建行（F2：lockout 表不随枚举增长）");

    store.shutdown().await?;
    Ok(())
}

// 跨租 fail-closed：A 种入 alice，B 视角 find → None / authenticate → InvalidUnknown / lockout_status → false
// （即使 A 已锁定 alice）。
#[tokio::test(flavor = "multi_thread")]
async fn credential_repo_cross_tenant_fail_closed() -> TestResult {
    let (_pg, store) = connect_pg().await?;
    store.run_migrations().await?;
    let repo = PgCredentialRepo::from_unverified_for_test(&store);
    let a = cred_tenant(CRED_TENANT_A)?;
    let b = cred_tenant(CRED_TENANT_B)?;
    repo.save(
        identity_scope(a),
        make_cred("alice", CRED_USER_ALICE, "correct", 1, a)?,
    )
    .await?;
    let now = cred_epoch(CRED_BASE_SECS);

    // 跨租 find → None（不泄露存在性）。
    assert!(
        repo.find_by_user_id(identity_scope(b), cred_uid(CRED_USER_ALICE)?)
            .await?
            .is_none(),
        "跨租 find → None"
    );
    // 跨租 authenticate → InvalidUnknown（跨租即未知）。
    assert_eq!(
        repo.authenticate(
            identity_scope(b),
            login_id("alice"),
            raw_password("correct"),
            now
        )
        .await?,
        AuthOutcome::InvalidUnknown,
        "跨租 authenticate → InvalidUnknown"
    );
    // 在 A 锁定 alice（5 次错），B 视角 lockout_status 仍 false（隔离）。
    for i in 1..=5 {
        repo.authenticate(
            identity_scope(a),
            login_id("alice"),
            raw_password("wrong"),
            cred_epoch(CRED_BASE_SECS + i),
        )
        .await?;
    }
    assert!(
        repo.lockout_status(
            identity_scope(a),
            login_id("alice"),
            cred_epoch(CRED_BASE_SECS + 5)
        )
        .await?,
        "A 视角 alice 已锁"
    );
    assert!(
        !repo
            .lockout_status(
                identity_scope(b),
                login_id("alice"),
                cred_epoch(CRED_BASE_SECS + 5)
            )
            .await?,
        "B 视角不受 A 锁定影响（跨租隔离）"
    );

    store.shutdown().await?;
    Ok(())
}

#[tokio::test(flavor = "multi_thread")]
async fn credential_repo_tenant_noop_conformance() -> TestResult {
    let (_pg, store) = connect_pg().await?;
    store.run_migrations().await?;
    let repo = PgCredentialRepo::from_unverified_for_test(&store);
    let a = cred_tenant(CRED_TENANT_A)?;
    let b = cred_tenant(CRED_TENANT_B)?;
    let alice_uid = cred_uid(CRED_USER_ALICE)?;
    let now = cred_epoch(CRED_BASE_SECS);
    let credential = make_cred("alice", CRED_USER_ALICE, "correct", 1, a)?;

    testkit::repo_conformance::assert_cross_tenant_noop(
        || async {
            repo.save(identity_scope(a), credential).await?;
            Ok::<(), Box<dyn std::error::Error + Send + Sync>>(())
        },
        || async {
            Ok::<bool, Box<dyn std::error::Error + Send + Sync>>(
                repo.find_by_user_id(identity_scope(a), alice_uid)
                    .await?
                    .is_some(),
            )
        },
        || async {
            Ok::<bool, Box<dyn std::error::Error + Send + Sync>>(
                repo.find_by_user_id(identity_scope(b), alice_uid)
                    .await?
                    .is_some(),
            )
        },
        || async {
            let outcome = repo
                .authenticate(
                    identity_scope(b),
                    login_id("alice"),
                    raw_password("correct"),
                    now,
                )
                .await?;
            if outcome == AuthOutcome::InvalidUnknown {
                Ok::<(), Box<dyn std::error::Error + Send + Sync>>(())
            } else {
                Err(format!("cross-tenant authenticate returned {outcome:?}").into())
            }
        },
        || async {
            Ok::<bool, Box<dyn std::error::Error + Send + Sync>>(
                repo.find_by_user_id(identity_scope(a), alice_uid)
                    .await?
                    .is_some(),
            )
        },
    )
    .await?;

    store.shutdown().await?;
    Ok(())
}

// 原子推进：连续 authenticate(错) 经仓储持久化累计——未达阈值未锁，第 5 次（窗口内）达阈值锁定。
#[tokio::test(flavor = "multi_thread")]
async fn credential_repo_accumulate_failures_then_locks() -> TestResult {
    let (_pg, store) = connect_pg().await?;
    store.run_migrations().await?;
    let repo = PgCredentialRepo::from_unverified_for_test(&store);
    let a = cred_tenant(CRED_TENANT_A)?;
    repo.save(
        identity_scope(a),
        make_cred("alice", CRED_USER_ALICE, "correct", 1, a)?,
    )
    .await?;

    for i in 1..5 {
        assert_eq!(
            repo.authenticate(
                identity_scope(a),
                login_id("alice"),
                raw_password("wrong"),
                cred_epoch(CRED_BASE_SECS + i)
            )
            .await?,
            AuthOutcome::InvalidKnownUser,
            "第 {i} 次失败"
        );
        assert!(
            !repo
                .lockout_status(
                    identity_scope(a),
                    login_id("alice"),
                    cred_epoch(CRED_BASE_SECS + i)
                )
                .await?,
            "未达阈值仍未锁"
        );
    }
    // 第 5 次（窗口内）→ 达阈值锁定（DB 持久化失败计数 = 5）。
    repo.authenticate(
        identity_scope(a),
        login_id("alice"),
        raw_password("wrong"),
        cred_epoch(CRED_BASE_SECS + 5),
    )
    .await?;
    assert!(
        repo.lockout_status(
            identity_scope(a),
            login_id("alice"),
            cred_epoch(CRED_BASE_SECS + 5)
        )
        .await?,
        "第 5 次达阈值锁定"
    );
    assert_eq!(
        db_failure_count(&store, CRED_TENANT_A, "alice").await?,
        5,
        "失败计数持久化推进至阈值"
    );

    store.shutdown().await?;
    Ok(())
}

// lazy-unlock：TTL 内仍锁；TTL 后 lockout_status 原子解锁（持久化清 locked_until）+ 计数从 1 重计。
#[tokio::test(flavor = "multi_thread")]
async fn credential_repo_lockout_lazy_unlocks_after_ttl() -> TestResult {
    let (_pg, store) = connect_pg().await?;
    store.run_migrations().await?;
    let repo = PgCredentialRepo::from_unverified_for_test(&store);
    let a = cred_tenant(CRED_TENANT_A)?;
    repo.save(
        identity_scope(a),
        make_cred("alice", CRED_USER_ALICE, "correct", 1, a)?,
    )
    .await?;
    for i in 1..=5 {
        repo.authenticate(
            identity_scope(a),
            login_id("alice"),
            raw_password("wrong"),
            cred_epoch(CRED_BASE_SECS + i),
        )
        .await?;
    }
    let lock_at = CRED_BASE_SECS + 5;

    // TTL 内仍锁。
    assert!(
        repo.lockout_status(
            identity_scope(a),
            login_id("alice"),
            cred_epoch(lock_at + LOCK_TTL_SECS - 1)
        )
        .await?,
        "TTL 内仍锁"
    );
    // TTL 后 lazy-unlock → false + 持久化清 locked_until。
    assert!(
        !repo
            .lockout_status(
                identity_scope(a),
                login_id("alice"),
                cred_epoch(lock_at + LOCK_TTL_SECS + 1)
            )
            .await?,
        "TTL 后 lazy-unlock 解锁"
    );
    assert!(
        db_locked_until(&store, CRED_TENANT_A, "alice")
            .await?
            .is_none(),
        "lazy-unlock 持久化清 locked_until"
    );
    // 解锁后再失败从 1 重计（不沿用旧计数）→ InvalidKnownUser、未锁。
    let after = lock_at + LOCK_TTL_SECS + 2;
    assert_eq!(
        repo.authenticate(
            identity_scope(a),
            login_id("alice"),
            raw_password("wrong"),
            cred_epoch(after)
        )
        .await?,
        AuthOutcome::InvalidKnownUser
    );
    assert!(
        !repo
            .lockout_status(identity_scope(a), login_id("alice"), cred_epoch(after))
            .await?,
        "重计未达阈值未锁"
    );

    store.shutdown().await?;
    Ok(())
}

// 成功登录原子清零失败计数（authenticate 内折叠 clear——不需独立 clear 端口）。
#[tokio::test(flavor = "multi_thread")]
async fn credential_repo_authenticate_success_clears_lockout() -> TestResult {
    let (_pg, store) = connect_pg().await?;
    store.run_migrations().await?;
    let repo = PgCredentialRepo::from_unverified_for_test(&store);
    let a = cred_tenant(CRED_TENANT_A)?;
    repo.save(
        identity_scope(a),
        make_cred("alice", CRED_USER_ALICE, "correct", 1, a)?,
    )
    .await?;

    // 4 次错（未达阈值 5，未锁）→ 失败计数持久化 = 4。
    for i in 1..=4 {
        repo.authenticate(
            identity_scope(a),
            login_id("alice"),
            raw_password("wrong"),
            cred_epoch(CRED_BASE_SECS + i),
        )
        .await?;
    }
    assert_eq!(
        db_failure_count(&store, CRED_TENANT_A, "alice").await?,
        4,
        "失败累积 4"
    );
    // 正确密码 → Authenticated + 原子清零失败计数。
    assert_eq!(
        repo.authenticate(
            identity_scope(a),
            login_id("alice"),
            raw_password("correct"),
            cred_epoch(CRED_BASE_SECS + 5)
        )
        .await?,
        AuthOutcome::Authenticated(cred_uid(CRED_USER_ALICE)?)
    );
    assert_eq!(
        db_failure_count(&store, CRED_TENANT_A, "alice").await?,
        0,
        "成功登录清零失败计数"
    );

    store.shutdown().await?;
    Ok(())
}

// apply_password_change CAS：期望不匹配 → VersionConflict；命中 → 替换 hash+version（authenticate 新密码真）；
// 查无 → CredentialNotFound；跨租（next 在 B）→ CredentialNotFound 且不动 A。
#[tokio::test(flavor = "multi_thread")]
async fn credential_repo_apply_password_change_cas() -> TestResult {
    let (_pg, store) = connect_pg().await?;
    store.run_migrations().await?;
    let repo = PgCredentialRepo::from_unverified_for_test(&store);
    let a = cred_tenant(CRED_TENANT_A)?;
    let b = cred_tenant(CRED_TENANT_B)?;
    repo.save(
        identity_scope(a),
        make_cred("alice", CRED_USER_ALICE, "pw1", 1, a)?,
    )
    .await?;
    let now = cred_epoch(CRED_BASE_SECS);

    // 期望版本不匹配 → VersionConflict。
    assert!(
        matches!(
            repo.apply_password_change(
                identity_scope(a),
                password_change(99, make_cred("alice", CRED_USER_ALICE, "pw2", 2, a)?)
            )
            .await,
            Err(IdentityError::VersionConflict)
        ),
        "期望不匹配 → VersionConflict"
    );
    let Some(after_conflict) = repo
        .find_by_user_id(identity_scope(a), cred_uid(CRED_USER_ALICE)?)
        .await?
    else {
        return Err("credential visible after stale CAS conflict".into());
    };
    assert_eq!(after_conflict.version(), 1, "stale CAS 不推进 version");
    assert!(
        password_matches("pw1", after_conflict.password_hash())?,
        "stale CAS 后旧密码仍有效"
    );
    assert!(
        !password_matches("pw2", after_conflict.password_hash())?,
        "stale CAS 后候选密码不得生效"
    );
    // 命中 → 替换 hash + version。
    repo.apply_password_change(
        identity_scope(a),
        password_change(1, make_cred("alice", CRED_USER_ALICE, "pw2", 2, a)?),
    )
    .await?;
    let Some(got) = repo
        .find_by_user_id(identity_scope(a), cred_uid(CRED_USER_ALICE)?)
        .await?
    else {
        return Err("credential visible after CAS hit".into());
    };
    assert_eq!(got.version(), 2, "CAS 命中后 version = 2");
    assert_eq!(
        repo.authenticate(
            identity_scope(a),
            login_id("alice"),
            raw_password("pw2"),
            now
        )
        .await?,
        AuthOutcome::Authenticated(cred_uid(CRED_USER_ALICE)?),
        "新密码验签真"
    );
    // 查无凭据 → CredentialNotFound。
    assert!(
        matches!(
            repo.apply_password_change(
                identity_scope(a),
                password_change(1, make_cred("ghost", CRED_USER_BOB, "x", 1, a)?)
            )
            .await,
            Err(IdentityError::CredentialNotFound)
        ),
        "查无 → CredentialNotFound"
    );
    // 跨租 bump（next 在 B）→ CredentialNotFound（key 派生自 next，B 无行），不动 A。
    assert!(
        matches!(
            repo.apply_password_change(
                identity_scope(b),
                password_change(2, make_cred("alice", CRED_USER_ALICE, "pw3", 3, b)?)
            )
            .await,
            Err(IdentityError::CredentialNotFound)
        ),
        "跨租 bump → CredentialNotFound"
    );
    let Some(still_a) = repo
        .find_by_user_id(identity_scope(a), cred_uid(CRED_USER_ALICE)?)
        .await?
    else {
        return Err("tenant A credential still present after cross-tenant bump".into());
    };
    assert_eq!(still_a.version(), 2, "跨租 bump 不动 A（仍 v2）");

    store.shutdown().await?;
    Ok(())
}

/// 两个持有同一 v1 快照的真实并发写者只能有一个 CAS 胜出；败者冲突且不覆盖胜者。
#[tokio::test(flavor = "multi_thread")]
async fn credential_repo_password_change_concurrent_writers_one_wins() -> TestResult {
    let (pg, owner) = connect_pg().await?;
    owner.run_migrations().await?;
    let app = connect_pg_rss_app_role(&pg, &owner).await?;
    let setup_repo = PgCredentialRepo::from_unverified_for_test(&app);
    let tenant = cred_tenant(CRED_TENANT_A)?;
    setup_repo
        .save(
            identity_scope(tenant),
            make_cred("alice", CRED_USER_ALICE, "pw-v1", 1, tenant)?,
        )
        .await?;

    let left = make_cred("alice", CRED_USER_ALICE, "pw-left", 2, tenant)?;
    let right = make_cred("alice", CRED_USER_ALICE, "pw-right", 2, tenant)?;
    let gate = crate::credential_repo::PasswordChangeCasPauseGate::new();
    let left_repo = PgCredentialRepo::from_unverified_for_test(&app)
        .with_password_change_post_update_pause(gate.clone());
    let left_task = tokio::spawn(async move {
        left_repo
            .apply_password_change(identity_scope(tenant), password_change(1, left))
            .await
    });
    tokio::time::timeout(std::time::Duration::from_secs(5), gate.wait_until_updated())
        .await
        .map_err(|_| "first CAS writer did not reach the post-update pause gate")?;

    let right_repo = PgCredentialRepo::from_unverified_for_test(&app);
    let mut right_task = tokio::spawn(async move {
        right_repo
            .apply_password_change(identity_scope(tenant), password_change(1, right))
            .await
    });
    assert!(
        tokio::time::timeout(std::time::Duration::from_millis(200), &mut right_task)
            .await
            .is_err(),
        "second CAS writer must remain pending while the first writer owns the row lock"
    );

    gate.release();
    let left_result = tokio::time::timeout(std::time::Duration::from_secs(5), left_task)
        .await
        .map_err(|_| "left CAS task timed out after release")?
        .map_err(|error| format!("left CAS task failed to join: {error}"))?;
    let right_result = tokio::time::timeout(std::time::Duration::from_secs(5), right_task)
        .await
        .map_err(|_| "right CAS task timed out after release")?
        .map_err(|error| format!("right CAS task failed to join: {error}"))?;
    assert!(
        left_result.is_ok(),
        "持锁的第一写者必须提交：{left_result:?}"
    );
    assert!(
        matches!(right_result, Err(IdentityError::VersionConflict)),
        "等待行锁的第二写者必须观察到 VersionConflict：{right_result:?}"
    );

    let Some((final_version, final_hash)) =
        owner_credential_snapshot(&owner, tenant, "alice").await?
    else {
        return Err("credential visible after concurrent CAS".into());
    };
    assert_eq!(final_version, 2, "并发 CAS 最终只推进至 v2");
    let final_hash = secure::PasswordHash::parse(&final_hash)?;
    assert!(
        password_matches("pw-left", &final_hash)?,
        "最终 hash 必须属于先持锁并提交的写者"
    );
    assert!(
        !password_matches("pw-right", &final_hash)?,
        "冲突写者不得覆盖胜出的 hash"
    );
    assert!(
        !password_matches("pw-v1", &final_hash)?,
        "成功 CAS 后 v1 密码必须失效"
    );

    app.shutdown().await?;
    owner.shutdown().await?;
    Ok(())
}

/// identity credential 的 Postgres retry 边界 conformance。
///
/// transient 用真实 tenant-scoped 事务更新 credentials：第一轮更新后返回 transient storage error，事务回滚；
/// 第二轮重建事务后提交。CAS conflict / permanent 走 production `apply_password_change`，证明不会盲目重试或提交副作用。
#[tokio::test(flavor = "multi_thread")]
async fn credential_repo_retry_boundary_conformance() -> TestResult {
    let (_pg, store) = connect_pg().await?;
    store.run_migrations().await?;
    let recorder = metrics_exporter_prometheus::PrometheusBuilder::new().build_recorder();
    let metrics_handle = recorder.handle();
    let repo = PgCredentialRepo::from_unverified_for_test(&store);
    let tenant = cred_tenant(CRED_TENANT_A)?;
    let retry_uid = cred_uid(CRED_USER_RETRY)?;
    let bob_uid = cred_uid(CRED_USER_BOB)?;
    let transient_next = make_cred("retry-alice", CRED_USER_RETRY, "pw-transient", 2, tenant)?;
    let conflict_next = make_cred("retry-alice", CRED_USER_RETRY, "pw-conflict", 3, tenant)?;
    let exhaustion_next = make_cred("retry-alice", CRED_USER_RETRY, "pw-exhausted", 3, tenant)?;
    let ghost_next = make_cred("ghost", CRED_USER_BOB, "pw-ghost", 1, tenant)?;
    repo.save(
        identity_scope(tenant),
        make_cred("retry-alice", CRED_USER_RETRY, "pw1", 1, tenant)?,
    )
    .await?;
    let transient_repo = PgCredentialRepo::from_unverified_for_test(&store)
        .with_password_change_fault("retry-alice", CredentialMutationFault::Transient, 1);
    let conflict_repo = PgCredentialRepo::from_unverified_for_test(&store);
    let permanent_repo = PgCredentialRepo::from_unverified_for_test(&store);
    let exhaustion_repo = PgCredentialRepo::from_unverified_for_test(&store)
        .with_password_change_fault("retry-alice", CredentialMutationFault::Transient, 3);

    metrics::with_local_recorder(&recorder, || {
        tokio::task::block_in_place(|| {
            tokio::runtime::Handle::current().block_on(
                testkit::repo_conformance::assert_retry_boundary_policy(
                    testkit::repo_conformance::RetryBoundaryCase::new(
                        testkit::repo_conformance::TransientSuccessPath::new(
                            || {
                                let transient_repo = &transient_repo;
                                let transient_next = transient_next.clone();
                                async move {
                                    transient_repo
                                        .apply_password_change(
                                            identity_scope(tenant),
                                            password_change(1, transient_next),
                                        )
                                        .await
                                }
                            },
                            || transient_repo.password_change_attempts("retry-alice"),
                            2,
                            || async {
                                let Some(got) = repo
                                    .find_by_user_id(identity_scope(tenant), retry_uid)
                                    .await?
                                else {
                                    return Ok::<usize, IdentityError>(0);
                                };
                                Ok::<usize, IdentityError>(usize::from(got.version() == 2))
                            },
                        ),
                        testkit::repo_conformance::ConflictPath::new(
                            || async {
                                conflict_repo
                                    .apply_password_change(
                                        identity_scope(tenant),
                                        password_change(99, conflict_next.clone()),
                                    )
                                    .await
                            },
                            || conflict_repo.password_change_attempts("retry-alice"),
                            || async {
                                let Some(got) = repo
                                    .find_by_user_id(identity_scope(tenant), retry_uid)
                                    .await?
                                else {
                                    return Ok::<usize, IdentityError>(0);
                                };
                                Ok::<usize, IdentityError>(usize::from(got.version() == 3))
                            },
                        ),
                        testkit::repo_conformance::PermanentPath::new(
                            || async {
                                permanent_repo
                                    .apply_password_change(
                                        identity_scope(tenant),
                                        password_change(1, ghost_next.clone()),
                                    )
                                    .await
                            },
                            || permanent_repo.password_change_attempts("ghost"),
                            || async {
                                Ok::<usize, IdentityError>(usize::from(
                                    repo.find_by_user_id(identity_scope(tenant), bob_uid)
                                        .await?
                                        .is_some(),
                                ))
                            },
                        ),
                        testkit::repo_conformance::TransientExhaustionPath::new(
                            || {
                                let exhaustion_repo = &exhaustion_repo;
                                let exhaustion_next = exhaustion_next.clone();
                                async move {
                                    exhaustion_repo
                                        .apply_password_change(
                                            identity_scope(tenant),
                                            password_change(2, exhaustion_next),
                                        )
                                        .await
                                }
                            },
                            || exhaustion_repo.password_change_attempts("retry-alice"),
                            3,
                            || async {
                                let Some(got) = repo
                                    .find_by_user_id(identity_scope(tenant), retry_uid)
                                    .await?
                                else {
                                    return Ok::<usize, IdentityError>(0);
                                };
                                Ok::<usize, IdentityError>(usize::from(got.version() != 2))
                            },
                        ),
                    ),
                    |error| conformance_retry_category(classify_identity_error(error)),
                ),
            )
        })
    })?;

    let rendered = metrics_handle.render();
    for expected in [
        "localtx_retry_attempts_total",
        "localtx_final_total",
        "localtx_attempts",
        "domain=\"identity\"",
        "contract_id=\"identity.password-change\"",
        "boundary=\"single_domain\"",
        "retry_class=\"transient\"",
        "retry_class=\"conflict\"",
        "retry_class=\"permanent\"",
        "final_status=\"committed\"",
        "final_status=\"rolled_back\"",
        "status=\"exhausted\"",
    ] {
        assert!(
            rendered.contains(expected),
            "production credential retry boundary omitted {expected}: {rendered}"
        );
    }

    store.shutdown().await?;
    Ok(())
}

/// #1704：真实 `rss_app` + `PgCredentialRepo` password-change LocalTx 后端矩阵。
#[tokio::test(flavor = "multi_thread")]
#[allow(clippy::unwrap_used)]
async fn identity_password_change_real_rss_app_localtx_matrix() -> TestResult {
    use std::sync::atomic::{AtomicUsize, Ordering};

    const LOCALTX_BACKEND_PROFILE_IDENTITY_PASSWORD_CHANGE: ::vocab::HttpRouteBinding<
        ::generated::http::identity_v1::password_change::RouteMarker,
        ::vocab::http::LocalTx,
    > = ::generated::http::identity_v1::password_change::ROUTE;
    const LOCALTX_BACKEND_PROVIDER_IDENTITY_PASSWORD_CHANGE: ::std::marker::PhantomData<(
        ::generated::http::identity_v1::password_change::RouteMarker,
        crate::PgCredentialRepo,
    )> = ::std::marker::PhantomData;
    let _typed_enrollment = LOCALTX_BACKEND_PROFILE_IDENTITY_PASSWORD_CHANGE;
    let _typed_provider = LOCALTX_BACKEND_PROVIDER_IDENTITY_PASSWORD_CHANGE;

    let (pg, owner) = connect_pg().await?;
    owner.run_migrations().await?;
    let app = connect_pg_rss_app_role(&pg, &owner).await?;
    let tenant_a = TenantId::parse(&uuid::Uuid::new_v4().to_string()).unwrap();
    let fixture_repo = PgCredentialRepo::from_unverified_for_test(&app);

    let commit_login = format!("pc-commit-{}", uuid::Uuid::new_v4().simple());
    let commit_user = uuid::Uuid::new_v4().to_string();
    fixture_repo
        .save(
            identity_scope(tenant_a),
            make_cred(&commit_login, &commit_user, "pw-v1", 1, tenant_a)?,
        )
        .await?;
    let commit_repo = PgCredentialRepo::from_unverified_for_test(&app);
    let commit_writes = AtomicUsize::new(0);
    ::testkit::localtx::assert_commit(::testkit::localtx::CommitCase::new(
        || async {
            commit_repo
                .apply_password_change(
                    identity_scope(tenant_a),
                    password_change(
                        1,
                        make_cred(&commit_login, &commit_user, "pw-v2", 2, tenant_a).map_err(
                            |error| {
                                testkit::localtx::ClassifiedError::new(
                                    testkit::ConformanceErrorCategory::Storage,
                                    IdentityError::Storage(error),
                                )
                            },
                        )?,
                    ),
                )
                .await
                .map_err(classified_identity_error)?;
            commit_writes.fetch_add(1, Ordering::Relaxed);
            Ok(())
        },
        || async {
            owner_credential_snapshot(&owner, tenant_a, &commit_login)
                .await
                .map(|snapshot| snapshot.map(|(version, _)| version))
                .map_err(|error| {
                    testkit::localtx::ClassifiedError::new(
                        testkit::ConformanceErrorCategory::Storage,
                        error,
                    )
                })
        },
        Some(2),
        || commit_writes.load(Ordering::Relaxed),
    ))
    .await?;
    let (_, committed_hash) = owner_credential_snapshot(&owner, tenant_a, &commit_login)
        .await?
        .ok_or("committed credential snapshot missing")?;
    assert!(password_matches(
        "pw-v2",
        &secure::PasswordHash::parse(&committed_hash)?
    )?);

    let missing_login = format!("pc-missing-{}", uuid::Uuid::new_v4().simple());
    let missing_user = uuid::Uuid::new_v4().to_string();
    let missing_repo = PgCredentialRepo::from_unverified_for_test(&app);
    assert!(matches!(
        missing_repo
            .apply_password_change(
                identity_scope(tenant_a),
                password_change(
                    1,
                    make_cred(&missing_login, &missing_user, "pw-missing", 2, tenant_a)?,
                ),
            )
            .await,
        Err(IdentityError::CredentialNotFound)
    ));
    assert_eq!(missing_repo.password_change_attempts(&missing_login), 1);
    assert_eq!(
        owner_credential_snapshot(&owner, tenant_a, &missing_login).await?,
        None
    );

    app.shutdown().await?;
    owner.shutdown().await?;
    Ok(())
}

#[tokio::test(flavor = "multi_thread")]
#[allow(clippy::unwrap_used)]
async fn identity_password_change_real_rss_app_validation_profile() -> TestResult {
    use std::sync::atomic::{AtomicUsize, Ordering};

    const LOCALTX_BACKEND_PROFILE_IDENTITY_PASSWORD_CHANGE: ::vocab::HttpRouteBinding<
        ::generated::http::identity_v1::password_change::RouteMarker,
        ::vocab::http::LocalTx,
    > = ::generated::http::identity_v1::password_change::ROUTE;
    const LOCALTX_BACKEND_PROVIDER_IDENTITY_PASSWORD_CHANGE: ::std::marker::PhantomData<(
        ::generated::http::identity_v1::password_change::RouteMarker,
        crate::PgCredentialRepo,
    )> = ::std::marker::PhantomData;
    let _typed_enrollment = LOCALTX_BACKEND_PROFILE_IDENTITY_PASSWORD_CHANGE;
    let _typed_provider = LOCALTX_BACKEND_PROVIDER_IDENTITY_PASSWORD_CHANGE;

    let (pg, owner) = connect_pg().await?;
    owner.run_migrations().await?;
    let app = connect_pg_rss_app_role(&pg, &owner).await?;
    let tenant_a = TenantId::parse(&uuid::Uuid::new_v4().to_string()).unwrap();
    let tenant_b = TenantId::parse(&uuid::Uuid::new_v4().to_string()).unwrap();
    let fixture_repo = PgCredentialRepo::from_unverified_for_test(&app);

    let validation_login = format!("pc-validation-{}", uuid::Uuid::new_v4().simple());
    let validation_user = uuid::Uuid::new_v4().to_string();
    fixture_repo
        .save(
            identity_scope(tenant_a),
            make_cred(&validation_login, &validation_user, "pw-v1", 1, tenant_a)?,
        )
        .await?;
    let validation_repo = PgCredentialRepo::from_unverified_for_test(&app);
    let validation_baseline = owner_credential_snapshot(&owner, tenant_a, &validation_login)
        .await?
        .ok_or("validation credential baseline missing")?;
    let validation_mutations = AtomicUsize::new(0);
    ::testkit::localtx::assert_rejected_no_write(::testkit::localtx::RejectedNoWriteCase::new(
        || async {
            let result = validation_repo
                .apply_password_change(
                    identity_scope(tenant_a),
                    password_change(
                        1,
                        make_cred(
                            &validation_login,
                            &validation_user,
                            "pw-invalid",
                            2,
                            tenant_b,
                        )
                        .map_err(|error| {
                            testkit::localtx::ClassifiedError::new(
                                testkit::ConformanceErrorCategory::Validation,
                                IdentityError::Storage(error),
                            )
                        })?,
                    ),
                )
                .await;
            let changed = owner_credential_snapshot(&owner, tenant_a, &validation_login)
                .await
                .map_err(|error| {
                    testkit::localtx::ClassifiedError::new(
                        testkit::ConformanceErrorCategory::Storage,
                        IdentityError::Storage(Box::new(error)),
                    )
                })?
                .is_some_and(|snapshot| snapshot != validation_baseline);
            validation_mutations.store(usize::from(changed), Ordering::Relaxed);
            result.map_err(|error| {
                testkit::localtx::ClassifiedError::new(
                    testkit::ConformanceErrorCategory::Validation,
                    error,
                )
            })
        },
        testkit::ConformanceErrorCategory::Validation,
        || async {
            owner_credential_snapshot(&owner, tenant_a, &validation_login)
                .await
                .map_err(|error| {
                    testkit::localtx::ClassifiedError::new(
                        testkit::ConformanceErrorCategory::Storage,
                        error,
                    )
                })
        },
        Some(validation_baseline.clone()),
        || validation_mutations.load(Ordering::Relaxed),
    ))
    .await?;
    let validation_hash = secure::PasswordHash::parse(&validation_baseline.1)?;
    assert!(password_matches("pw-v1", &validation_hash)?);
    assert!(!password_matches("pw-invalid", &validation_hash)?);

    app.shutdown().await?;
    owner.shutdown().await?;
    Ok(())
}

